import { useEffect, useState } from 'react';
import api from '../api/axiosInstance';

const REFRESH_MS = 10 * 60 * 1000;

// Banners whose title was generated by the server ("Banner 2026-10-21T...")
// have no real title to show.
export const isGeneratedBannerTitle = (title) => /^Banner \d{4}-\d{2}-\d{2}T/.test(String(title || ''));

/// Promo banners for the zone at `position` ({ lat, lng }), from
/// `/users/banners` (rider) or `/drivers/banners` (driver).
///
/// Returns `{ banners, anyBanners, loaded }`. `loaded` stays false until a
/// request succeeds, so callers can keep showing what they had before.
/// `anyBanners` is false when the admin has set up no banners at all for this
/// app, as opposed to none for this zone. Without a position the server sends
/// only the all-zone banners.
export const useZoneBanners = (path, position) => {
  const [state, setState] = useState({ banners: [], anyBanners: false, loaded: false });
  const lat = Number(position?.lat);
  const lng = Number(position?.lng);
  const hasPosition = Number.isFinite(lat) && Number.isFinite(lng);
  // Re-fetch when the person moves about a kilometre, not on every GPS tick.
  const latKey = hasPosition ? lat.toFixed(2) : '';
  const lngKey = hasPosition ? lng.toFixed(2) : '';

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const res = await api.get(path, { params: latKey ? { lat: latKey, lng: lngKey } : {} });
        const payload = res?.data ?? res ?? {};
        if (cancelled) return;
        setState({
          banners: Array.isArray(payload.results) ? [...payload.results] : [],
          anyBanners: Boolean(payload.any_banners),
          loaded: true,
        });
      } catch {
        // Banners are decoration; a failed fetch keeps the last good set.
      }
    };

    load();
    const timer = setInterval(load, REFRESH_MS);
    return () => {
      cancelled = true;
      clearInterval(timer);
    };
  }, [path, latKey, lngKey]);

  return state;
};
